import app.routia.ProgressWidgetData;
import java.time.*;
import java.util.*;
public class ProgressWidgetDataTest {
    static int checks;
    static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    static ProgressWidgetData.Point p(String day,int level,Double amount,String unit){return new ProgressWidgetData.Point(LocalDate.parse(day),level,amount,unit);}
    public static void main(String[] args){
        LocalDate today=LocalDate.of(2026,10,24),created=LocalDate.of(2026,9,28);
        List<ProgressWidgetData.Point> points=List.of(p("2026-09-27",2,999d,"分"),p("2026-09-30",2,10d,"分"),p("2026-10-01",1,5d,"分"),p("2026-10-02",2,null,""),p("2026-10-03",3,20d,"分"),p("2026-10-04",1,0d,"分"),p("2026-10-05",0,999d,"分"),p("2026-10-20",2,10d,"分"),p("2026-10-22",2,10d,"回"),p("2026-10-23",2,5d,"分"),p("2026-10-25",2,999d,"分"));
        Set<LocalDate> tickets=Set.of(LocalDate.of(2026,10,21),today);
        var report=ProgressWidgetData.build(points,tickets,created,today,"time","分",10);
        check(report.monthDays()==7,"Only actual achievements in this month count");
        check(report.totalDays()==8,"Cumulative days exclude future, pre-creation and zero-level records");
        check(report.monthAmount()==40,"Month total includes minimum and full amounts");
        check(report.totalAmount()==50,"Cumulative amount includes previous months");
        check(report.monthAmounts()==5,"Missing and other-unit amounts are not zero measurements");
        check(report.totalAmounts()==6,"Cumulative numeric coverage stays distinct");
        check(report.streak()==3,"Tickets bridge streak without adding achieved days");
        check(report.shades().length==31,"Full month is rendered");
        check(report.shades()[1]==2,"Missing amount retains normal achievement shade");
        check(report.shades()[2]==4,"Greatest amount has strongest shade");
        check(report.shades()[3]==1,"Explicit zero is recorded but not a high amount");
        check(report.shades()[20]==5,"Closed ticket day is red");
        check(report.shades()[21]==2,"Wrong-unit amount falls back to achievement grade");
        check(report.shades()[23]==0,"No ticket is shown for unfinished today");
        check(report.shades()[24]==-1&&report.shades()[30]==-1,"Future cells are not missed days");
        var grade=ProgressWidgetData.build(points,tickets,created,today,"check","",0);
        check(grade.monthDays()==7,"Check tasks also count minimum achievement");
        check(grade.shades()[0]==1&&grade.shades()[2]==4,"Check tasks retain achievement intensity");
        var empty=ProgressWidgetData.build(List.of(),Set.of(),today,today,"count","回",1);
        check(empty.monthDays()==0&&empty.streak()==0,"New habit has no fabricated progress");
        check(empty.monthAmounts()==0,"No entries means no numeric measurements");
        check(empty.shades()[22]==-1&&empty.shades()[23]==0,"Pre-creation days are distinguished from unrecorded today");
        var zero=ProgressWidgetData.build(List.of(new ProgressWidgetData.Point(today,1,0d,"回")),Set.of(),today,today,"count","回",10);
        check(zero.monthAmounts()==1&&zero.monthAmount()==0,"A measured zero differs from a missing value");
        var invalid=ProgressWidgetData.build(List.of(new ProgressWidgetData.Point(today,2,Double.NaN,"回")),Set.of(),today,today,"count","回",10);
        check(invalid.monthDays()==1&&invalid.monthAmounts()==0,"Non-finite values never contaminate totals");
        var negative=ProgressWidgetData.build(List.of(new ProgressWidgetData.Point(today,2,-1d,"回")),Set.of(),today,today,"count","回",10);
        check(negative.monthAmounts()==0,"Negative quantities are not summed");
        LocalDate november=LocalDate.of(2026,11,1);
        var next=ProgressWidgetData.build(List.of(p("2026-10-31",2,10d,"分")),Set.of(),created,november,"time","分",10);
        check(next.monthDays()==0&&next.monthAmount()==0,"Month rollover resets only the current month");
        check(next.totalAmount()==10&&next.totalDays()==1,"Month rollover preserves cumulative totals");
        check(next.streak()==1,"Yesterday's streak survives the start of a new month");
        LocalDate leap=LocalDate.of(2028,2,29);
        var feb=ProgressWidgetData.build(List.of(new ProgressWidgetData.Point(leap,3,1d,"回")),Set.of(),leap.withDayOfMonth(1),leap,"count","回",1);
        check(feb.shades().length==29&&feb.shades()[28]==4,"Leap-day calendar and amount are included");
        check(report.week().size()==7,"Weekly graph always has seven days");
        check(report.week().get(0).day().equals(LocalDate.of(2026,10,19)),"Week starts on Monday");
        check(report.week().get(6).day().equals(LocalDate.of(2026,10,25)),"Week ends on Sunday");
        check(report.week().get(1).amount()==10d,"Weekly bars retain daily numeric amount");
        check(report.week().get(2).ticket()&&report.week().get(2).level()==0,"Ticket is a rest, never an achieved bar");
        check(report.week().get(3).amount()==null&&report.week().get(3).level()==2,"Other-unit measurement remains missing with achievement preserved");
        check(report.week().get(5).available()&&!report.week().get(5).ticket(),"Today is available and has no premature ticket");
        check(!report.week().get(6).available()&&report.week().get(6).level()==0,"Future achievement is not rendered");
        check(!empty.week().get(4).available()&&empty.week().get(5).available(),"Pre-creation day is unavailable");
        check(zero.week().get(5).amount()==0d,"Measured zero survives weekly projection");
        check(invalid.week().get(5).amount()==null&&negative.week().get(5).amount()==null,"Invalid measurements do not become bars");
        check(next.week().get(5).amount()==10d,"Week across a month boundary preserves prior-month bars");
        check(feb.week().get(1).day().equals(leap)&&feb.week().get(1).level()==3,"Leap day remains in correct weekly column");
        var year=ProgressWidgetData.build(List.of(p("2026-12-31",2,7d,"回")),Set.of(),created,LocalDate.of(2027,1,1),"count","回",1);
        check(year.week().get(3).amount()==7d&&year.week().get(4).day().getYear()==2027,"Week across year boundary retains exact dates");
        var never=ProgressWidgetData.build(List.of(),Set.of(),created,today,"time","分",15);
        check(never.totalDays()==0&&never.streak()==0,"A never-completed habit cannot become a success");
        check(ProgressWidgetData.summary(never).equals("🔥 連続0日 / ✅ 累計0日"),"Only the two requested counts appear on one line");
        var yesterdayOnly=ProgressWidgetData.build(List.of(p("2026-10-23",1,null,"")),Set.of(),created,today,"check","",0);
        check(yesterdayOnly.totalDays()==1&&yesterdayOnly.week().get(5).level()==0,"Yesterday's success never marks today as achieved");
        var broken=ProgressWidgetData.build(List.of(p("2026-10-22",2,null,"")),Set.of(),created,today,"check","",0);
        check(broken.streak()==0&&broken.totalDays()==1,"A broken streak resets to zero while cumulative achievements remain");
        var restarted=ProgressWidgetData.build(List.of(p("2026-10-22",2,null,""),p("2026-10-24",1,null,"")),Set.of(),created,today,"check","",0);
        check(restarted.streak()==1&&restarted.totalDays()==2,"Resuming after a break restarts at one without losing cumulative days");
        var protectedRest=ProgressWidgetData.build(List.of(p("2026-10-22",2,null,"")),Set.of(LocalDate.of(2026,10,23)),created,today,"check","",0);
        check(protectedRest.streak()==1&&protectedRest.totalDays()==1,"Protected rest preserves but never increases actual achievement days");
        var firstOfWeek=ProgressWidgetData.build(List.of(p("2026-10-25",3,null,"")),Set.of(),created,LocalDate.of(2026,10,26),"check","",0);
        check(firstOfWeek.week().get(0).level()==0&&firstOfWeek.week().get(0).available(),"Weekly rollover cannot copy Sunday's success into Monday");
        var midnight=ProgressWidgetData.build(List.of(p("2026-10-24",1,null,"")),Set.of(),created,LocalDate.of(2026,10,25),"check","",0);
        check(midnight.totalDays()==1&&midnight.week().get(6).level()==0,"After midnight, yesterday remains cumulative but today is unachieved");
        System.out.println("PASS "+checks+" progress-widget assertions");
    }
}
